questions.answer_markdown:
互斥资源：缓冲区只能互斥访问，因此设置互斥信号量 mutex。
同步问题：
P1​
、
P2​
因为奇数的放置与取用而同步，设同步信号量 odd；
P1​
、
P3​
因为偶数的放置与取用而同步，设置同步信号量 even；
P1​
、
P2​
、
P3​
因为共享缓冲区，设同步信号量 empty, 初值为 N。程序如下：

semaphore mutex=1;
semaphore odd=0, even=0;
semaphore empty=N;

P1() {
    while (true) {
        x = produce();   // 生成一个数
        P(empty);        // 判断缓冲区是否有空单元
        P(mutex);        // 缓冲区是否被占用
        put();
        V(mutex);        // 释放缓冲区
        if (x % 2 == 0)
            V(even);     // 如果是偶数，向 P3 发出信号
        else
            V(odd);      // 如果是奇数，向 P2 发出信号
    }
}

P2() {
    while (true) {
        P(odd);          // 收到 P1 发来的信号，已产生一个奇数
        P(mutex);        // 缓冲区是否被占用
        getodd();
        V(mutex);        // 释放缓冲区
        V(empty);        // 向 P1 发信号，多出一个空单元
        countodd();
    }
}

P3() {
    while (true) {
        P(even);         // 收到 P1 发来的信号，已产生一个偶数
        P(mutex);        // 缓冲区是否被占用
        geteven();
        V(mutex);        // 释放缓冲区
        V(empty);        // 向 P1 发信号，多出一个空单元
        counteven();
    }
}

