struct Arc {
  uint32_t id;
  uint32_t ip;
  int metric;
};

struct Net {
  uint32_t prefix;
  uint32_t mask;
  int metric;
};

struct LNode {
  LNode *next;
  // flag == 1：链路连接到路由器
  // flag == 2：链路连接到子网
  int flag;
  union NetOrArc {
    Net net;
    Arc arc;
  };
};

